import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.DUFi_nbG.js";const h=JSON.parse('{"title":"F3: Touchless Video Playback Engine & Kitchen Gesture Map","description":"","frontmatter":{},"headers":[],"relativePath":"features/F3-kitchen-gesture-map.md","filePath":"features/F3-kitchen-gesture-map.md"}'),n={name:"features/F3-kitchen-gesture-map.md"};function o(r,e,c,l,p,d){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="f3-touchless-video-playback-engine-kitchen-gesture-map" tabindex="-1">F3: Touchless Video Playback Engine &amp; Kitchen Gesture Map <a class="header-anchor" href="#f3-touchless-video-playback-engine-kitchen-gesture-map" aria-label="Permalink to &quot;F3: Touchless Video Playback Engine &amp; Kitchen Gesture Map&quot;">​</a></h1><h2 id="_1-description-command-mappings" tabindex="-1">1. Description &amp; Command Mappings <a class="header-anchor" href="#_1-description-command-mappings" aria-label="Permalink to &quot;1. Description &amp; Command Mappings&quot;">​</a></h2><p>The system maps recognized biometric gestures to specific HTML5 video actions:</p><ul><li><code>Open_Palm</code>: Pauses playback (<code>videoRef.current.pause()</code>).</li><li><code>Closed_Fist</code>: Resumes playback (<code>videoRef.current.play()</code>).</li><li><code>Pointing_Up</code>: Jumps forward 10 seconds (<code>videoRef.current.currentTime += 10</code>).</li><li><code>Victory</code> (Peace Sign): Jumps backward 10 seconds.</li><li><code>Thumb_Up</code>: Volume up / step complete.</li></ul><h2 id="_2-state-mapping-diagram" tabindex="-1">2. State Mapping Diagram <a class="header-anchor" href="#_2-state-mapping-diagram" aria-label="Permalink to &quot;2. State Mapping Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Palm[Open Palm] --&gt;|Command| Pause[Pause Video]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Fist[Closed Fist] --&gt;|Command| Play[Play Video]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Point[Pointing Up] --&gt;|Command| Forward[Seek +10s]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Peace[Victory Sign] --&gt;|Command| Rewind[Seek -10s]</span></span></code></pre></div><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;I designed the gesture vocabulary specifically around natural kitchen movements. An Open Palm acts as an intuitive stop sign to immediately halt the video, while curling fingers into a Closed Fist signals the player to resume. Pointing an index finger forward advances the tutorial by 10 seconds, allowing cooks to quickly re-sync with steps. By directly manipulating the HTML5 video element&#39;s DOM properties rather than wrapping third-party players, action execution is instant and deterministic.&quot;</p>`,8)])])}const u=a(n,[["render",o]]);export{h as __pageData,u as default};
